"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def CHECK_PASSWORD(password):
    if (len(password) < 8):
        return False
    has_number = False
    has_uppercase = False
    for c in password:
        if c.isdigit():
            has_number = True
        elif c.isupper():
            has_uppercase = True
    if (has_number and has_uppercase):
        return True
    else:
        return False
